CREATE OR REPLACE FUNCTION mission_generic_owner.c8_input_proof_assert_v1(p_work uuid, p_lease uuid, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;sd jsonb;pf jsonb;snap jsonb;manual_q jsonb;manual_sealed jsonb;manual_proof jsonb;manual_handoff jsonb;manual_authorized boolean:=false;
BEGIN
 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 select * into strict w from mission_generic_owner.work_items where id=p_work;
 IF w.id='48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'C889_CONTEXT24_RUNTIME_CLOSED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) THEN
  manual_q:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
  manual_sealed:=mission_generic_owner.c1266_historical_work_v1(w.id);
  manual_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  IF manual_q IS NULL OR manual_sealed IS NULL OR manual_proof IS NULL
   OR manual_proof->>'runtime_authorized' IS DISTINCT FROM 'true'
   OR manual_proof->>'execution_context' IS DISTINCT FROM 'staff_mission'
   OR manual_proof->'admission' IS DISTINCT FROM jsonb_build_object('schema_version','c1266-staff-admission-authority/3','kind','staff_finite','resource_scope','staff_simulation','finite_admission_sha256',public.combat_v2_sha256(manual_q),'admission_id',manual_q->>'start_receipt_id','location_id',manual_q->>'location_id')
   OR manual_sealed->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
   OR manual_sealed->'admission' IS DISTINCT FROM manual_proof->'admission'
   OR manual_sealed->>'binding_sha256' IS DISTINCT FROM manual_proof->>'binding_sha256'
   OR manual_sealed->>'financial_qualification_sha256' IS DISTINCT FROM manual_proof->>'financial_qualification_sha256'
   OR manual_sealed->>'c7_budget_qualification_sha256' IS DISTINCT FROM manual_proof->>'c7_budget_qualification_sha256'
   OR manual_proof->>'c7_budget_qualification_sha256' IS DISTINCT FROM manual_q->>'budget_qualification_sha256'
  THEN RAISE EXCEPTION 'MANUAL_STAFF_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
  manual_authorized:=true;
 ELSIF EXISTS(SELECT 1 FROM mission_generic_owner.dispatch_admissions ad JOIN mission_factory_owner.editor_release_readiness rr ON rr.singleton
 WHERE ad.master_session_id=w.master_session_id
 AND ad.c7_budget_qualification_sha256=rr.canonical_preimage::jsonb#>>'{config,c1266_clean_staff,c7_budget_qualification_sha256}')
 AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE
 OR mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true) IS NULL)
 THEN RAISE EXCEPTION 'C1266_CLEAN_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
 select da.details into strict sd from mission_narrative_internal.dispatch_audit da where da.receipt_id=w.dispatch_receipt_id and da.event_code='c8_count_started';
 select da.details into strict pf from mission_narrative_internal.dispatch_audit da where da.receipt_id=w.dispatch_receipt_id and da.event_code='c8_count_success';
 IF manual_authorized AND (sd->>'work_id' IS DISTINCT FROM w.id::text OR pf->>'work_id' IS DISTINCT FROM w.id::text
  OR sd->>'execution_context' IS DISTINCT FROM 'staff_mission'
  OR sd->>'provider_input_contract_version' IS DISTINCT FROM 'mission-generic-provider-input/5'
  OR sd->>'admission_sha256' IS DISTINCT FROM public.combat_v2_sha256(manual_proof->'admission')
  OR sd->>'c7_budget_qualification_sha256' IS DISTINCT FROM manual_proof->>'c7_budget_qualification_sha256'
  OR pf->>'generation_request_sha256' IS DISTINCT FROM sd->>'generation_request_sha256')
 THEN RAISE EXCEPTION 'MANUAL_STAFF_COUNT_PROOF_BINDING' USING ERRCODE='40001';END IF;
 IF manual_authorized AND sd->>'lease_id' IS DISTINCT FROM p_lease::text THEN
  manual_handoff:=mission_generic_owner.counted_resume_evidence_v1(w.id,p_lease);
 END IF;
 snap:=mission_generic_owner.c8_policy_snapshot_v1(w.id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  DECLARE proof5 jsonb;
  BEGIN proof5:=CASE WHEN manual_authorized THEN manual_proof ELSE mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) END;
   IF proof5 IS NULL OR sd->>'provider_input_contract_version' IS DISTINCT FROM (CASE WHEN mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL THEN 'mission-generic-provider-input/6' ELSE 'mission-generic-provider-input/5' END)
    OR sd->>'admission_sha256' IS DISTINCT FROM public.combat_v2_sha256(proof5->'admission')
    OR sd->>'c7_budget_qualification_sha256' IS DISTINCT FROM proof5->>'c7_budget_qualification_sha256'
    OR sd->>'policy_snapshot_sha256' IS DISTINCT FROM public.combat_v2_sha256(snap)
   THEN RAISE EXCEPTION 'C1266_INPUT5_IMMUTABLE_PROOF' USING ERRCODE='40001';END IF;
  END;
 END IF;
 if p_policy is null or not(p_policy ?& array['model','reasoning_effort','max_output_tokens','store','payload_sha256','input_measurement_id','provider_request_sha256']) or p_policy-'model'-'reasoning_effort'-'max_output_tokens'-'store'-'payload_sha256'-'input_measurement_id'-'provider_request_sha256'<>'{}'::jsonb or sd->>'measurement_id' is distinct from p_policy->>'input_measurement_id' or sd->>'generation_request_sha256' is distinct from p_policy->>'provider_request_sha256' or (sd->>'lease_id' is distinct from p_lease::text AND (NOT manual_authorized OR manual_handoff IS NULL)) or pf->>'measurement_id' is distinct from sd->>'measurement_id' or pf->>'generation_allowed' is distinct from 'true' or sd->>'policy_snapshot_sha256' is distinct from public.combat_v2_sha256(snap) or exists(select 1 from mission_narrative_internal.dispatch_audit where receipt_id=w.dispatch_receipt_id and event_code='c8_count_unknown') then raise exception 'C8_INPUT_PROOF_STALE' using errcode='40001';end if;
 return pf;
END $function$

