  if(!exact(realization,['segments','profile_audit',...(staff?['memoria']:[])])
    ||!Array.isArray(realization.segments)||realization.segments.length<1||realization.segments.length>24)
    throw Error('MISSION_SEGMENTED_OUTPUT_INVALID');
