  for(const part of realization.segments){
    if(!exact(part,['kind','text','slot_id','actor_key']))throw Error('MISSION_SEGMENTED_PART_INVALID');
    if(part.kind==='prose'){
      if(!text(part.text)||part.text.length>4500||part.slot_id!==null||part.actor_key!==null
