      || !key(a.actor_key) || actors.has(a.actor_key)
      || ['role_in_phase','goal_private','known_facts_private','public_portrayal'].some(k=>!prose(a[k])))
      throw Error('MISSION_DIRECTOR_ACTOR_INVALID');
    actors.add(a.actor_key);
